"use strict";(self.webpackChunkopenlabops_wiki=self.webpackChunkopenlabops_wiki||[]).push([[7721],{9435(e){e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"wikiSidebar":[{"type":"link","href":"/openlabops/","label":"OpenLabOps Wiki","docId":"intro","unlisted":false},{"type":"link","href":"/openlabops/architecture","label":"System Architecture","docId":"architecture","unlisted":false},{"type":"link","href":"/openlabops/security","label":"Security Policy & Key Lifecycle","docId":"security","unlisted":false},{"type":"link","href":"/openlabops/testing","label":"Testing Methodology & Sandbox","docId":"testing","unlisted":false},{"type":"link","href":"/openlabops/methodology","label":"Antigravity Vibe Coding & AI SRE","docId":"methodology","unlisted":false},{"type":"category","label":"CLI Applications & Internals","items":[{"type":"link","href":"/openlabops/apps/onboarding-and-compiler","label":"Onboarding, Inventory & Compiler","docId":"apps/onboarding-and-compiler","unlisted":false},{"type":"link","href":"/openlabops/apps/fleet-and-ssh","label":"Fleet Operations & SSH Lifecycle","docId":"apps/fleet-and-ssh","unlisted":false},{"type":"link","href":"/openlabops/apps/ops-and-helpers","label":"Config, Backup & Helper Tools","docId":"apps/ops-and-helpers","unlisted":false}],"collapsed":true,"collapsible":true}]},"docs":{"apps/fleet-and-ssh":{"id":"apps/fleet-and-ssh","title":"Fleet Operations & SSH Lifecycle","description":"These tools live in tools/bin/ and run with zero external Python dependencies ([INV-01]). Tasks requiring Ansible execution are dispatched remotely to Gitea Actions via tools/lib/core/gitea_api.py.","sidebar":"wikiSidebar"},"apps/onboarding-and-compiler":{"id":"apps/onboarding-and-compiler","title":"Onboarding, Inventory & Compiler","description":"These commands live in bin/ and power Day-0 cluster bootstrap, dynamic node onboarding, hardware discovery, manifest compilation, and sandbox testing.","sidebar":"wikiSidebar"},"apps/ops-and-helpers":{"id":"apps/ops-and-helpers","title":"Config, Backup & Helper Tools","description":"---","sidebar":"wikiSidebar"},"architecture":{"id":"architecture","title":"System Architecture","description":"OpenLabOps is a Zero-Dependency Declarative Homelab Operations Framework designed around strict separation of concerns: immutable framework contracts, declarative site parameters, and live probed machine telemetry are decoupled across three tiers and four downstream GitOps repositories.","sidebar":"wikiSidebar"},"intro":{"id":"intro","title":"OpenLabOps Wiki","description":"OpenLabOps is an open-source, turnkey operations control hub and GitOps management framework for modern homelabs and private Linux fleets. Built with 100% Python 3 standard library and stateless Ansible playbooks, it delivers Day-0 cluster onboarding, three-phase zero-downtime SSH key rotation, live sensory hardware discovery, and declarative GitOps synchronization without external Python dependencies (NO pip, NO requests, NO pyyaml).","sidebar":"wikiSidebar"},"methodology":{"id":"methodology","title":"Antigravity Vibe Coding & AI SRE","description":"OpenLabOps was built from the ground up using Google Antigravity (AGY) Vibe Coding\u2014a structured human-AI engineering workflow where the human architect defines hard invariants and design intent, and AI coding agents execute implementation, testing, and verification inside strict guardrails.","sidebar":"wikiSidebar"},"security":{"id":"security","title":"Security Policy & Key Lifecycle","description":"OpenLabOps enforces a zero-trust, zero-plaintext-credentials security model across the control workstation, GitOps federation, and managed Linux fleet.","sidebar":"wikiSidebar"},"testing":{"id":"testing","title":"Testing Methodology & Sandbox","description":"OpenLabOps validates every release end-to-end against real Linux containers and real CLI binaries\u2014never mock-only bypasses.","sidebar":"wikiSidebar"}}}}')}}]);